import{_ as t,c as a,o as s,a3 as o}from"./chunks/framework.BNw1pucY.js";const u=JSON.parse('{"title":"Migrate an early-alpha project","description":"Move a hosted Agent SDK architecture v1 project to v2 through a reviewed pull request.","frontmatter":{"title":"Migrate an early-alpha project","description":"Move a hosted Agent SDK architecture v1 project to v2 through a reviewed pull request."},"headers":[],"relativePath":"guides/migrate.md","filePath":"guides/migrate.md"}'),i={name:"guides/migrate.md"};function r(n,e,l,d,h,c){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="migrate-an-early-alpha-project-to-architecture-v2" tabindex="-1">Migrate an early-alpha project to architecture v2 <a class="header-anchor" href="#migrate-an-early-alpha-project-to-architecture-v2" aria-label="Permalink to &quot;Migrate an early-alpha project to architecture v2&quot;">​</a></h1><p>Use this guide only for an Agent SDK project deployed on architecture v1 during the early alpha. Every other project already runs on v2.</p><h2 id="check-whether-your-project-needs-migration" tabindex="-1">Check whether your project needs migration <a class="header-anchor" href="#check-whether-your-project-needs-migration" aria-label="Permalink to &quot;Check whether your project needs migration&quot;">​</a></h2><p>Your project needs migration if any of these is true:</p><ul><li><code>package.json</code> depends on <code>@cursor/july</code>.</li><li>A script or CI job runs the early-alpha CLI.</li><li>The agent sets <code>architecture: &quot;v1&quot;</code> or <code>runtime: &quot;grokbot&quot;</code>.</li><li>The project has <code>bot/storage.ts</code> or <code>agent/storage.ts</code>.</li><li>An SCM channel credential is a literal value.</li><li>Code uses a <code>/v1</code> continuation selector.</li><li>A reminder uses an anonymous <code>run</code> or <code>until</code> function.</li><li>A peer connection reads its URL from a <code>*_MCP_URL</code> secret.</li><li><code>agent-sdk deployment get &lt;slug&gt;</code> doesn&#39;t print <code>architecture: v2</code>.</li></ul><p><code>agent-sdk migrate</code> checks the source for these signals and prints <code>Nothing to migrate.</code> when it finds none. It doesn&#39;t check scripts, CI jobs, or the hosted deployment.</p><p>To swap the early-alpha package, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @cursor/july</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @grok/agent-sdk@latest</span></span></code></pre></div><p>An existing <code>agent/</code> folder still works.</p><h2 id="start-the-migration" tabindex="-1">Start the migration <a class="header-anchor" href="#start-the-migration" aria-label="Permalink to &quot;Start the migration&quot;">​</a></h2><p>Commit and push the source first. <code>agent-sdk migrate</code> starts a Cursor cloud agent on that pushed ref, and the agent opens a pull request without deploying.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent-sdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent-sdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>To migrate a pushed source outside your checkout, pass <code>--repo</code>, <code>--ref</code>, and <code>--path</code>. The <a href="./../reference/cli.html#migrate">CLI reference</a> lists every flag.</p><p>You can also ask a coding agent in your checkout to follow the bundled <code>bdk-migrate-v2</code> skill. If the project relies on a v1 capability that has no v2 path, the agent stops and names the blocker.</p><h2 id="review-the-pull-request" tabindex="-1">Review the pull request <a class="header-anchor" href="#review-the-pull-request" aria-label="Permalink to &quot;Review the pull request&quot;">​</a></h2><p>Before you merge, check that the pull request:</p><ul><li>Uses <code>@grok/agent-sdk</code> and <code>agent-sdk</code>, and removes <code>architecture: &quot;v1&quot;</code>.</li><li>Moves durable state to <code>ctx.host.kv</code> or <code>ctx.host.files</code>, reads secrets inside the handler that needs them, and expects hosted routes to return <code>202</code>.</li><li>Passes every SCM credential as <code>{ secretName: &quot;NAME&quot; }</code>. <code>agent-sdk validate</code> warns about a literal or <code>process.env</code> getter while <code>architecture: &quot;v1&quot;</code> is set, and fails once you remove it.</li><li>Replaces each peer URL secret, such as <code>BUILDER_MCP_URL</code>, with <code>defineConnection({ agent: &quot;&lt;slug&gt;&quot; })</code>. Check each slug and any TODO the agent left.</li><li>Lists unsupported behavior, follow-ups, and the checks it ran or handed off.</li></ul><h2 id="choose-a-cutover" tabindex="-1">Choose a cutover <a class="header-anchor" href="#choose-a-cutover" aria-label="Permalink to &quot;Choose a cutover&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cutover</th><th>What happens</th><th>Choose it when</th></tr></thead><tbody><tr><td>Same slug</td><td>v2 copies the v1 secrets and replaces v1 once it starts. You can&#39;t undo it, and it deletes v1&#39;s hosted sessions, KV, files, and eval runs.</td><td>A short outage and an empty v2 state are fine.</td></tr><tr><td>New slug</td><td>v1 keeps serving while you test v2. Move senders to the new URL, then delete v1.</td><td>You use Slack, webhooks, or hosted state.</td></tr></tbody></table><p>With a new slug, point the trial at a test repository so the two deployments don&#39;t both act on the same events.</p><h2 id="deploy-after-merge" tabindex="-1">Deploy after merge <a class="header-anchor" href="#deploy-after-merge" aria-label="Permalink to &quot;Deploy after merge&quot;">​</a></h2><p>Deploy from the merged, pushed ref. Reuse every <code>--cursor-events-repo</code> value from v1, and move every <code>--allow-domain</code> value into <code>hosting.egressDomains</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent-sdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --slug</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">existing-or-new-slu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Then follow the checklist that <code>agent-sdk migrate</code> printed:</p><ol><li>Deploy each agent folder separately by running <code>agent-sdk deploy --dir &lt;agent-folder&gt;</code> once for each one.</li><li>For each Slack agent, run <code>agent-sdk slack create --env prod --dir &lt;agent-folder&gt;</code>. Then uninstall the old app and invite the new bot to its channels.</li><li>For a <a href="./agent-to-agent.html">peer connection</a>, deploy both agents to the same team. Then delete each peer URL secret the pull request lists with <code>agent-sdk secret delete &lt;slug&gt; NAME</code>.</li><li>For a new slug, add each secret with <code>agent-sdk secret set &lt;slug&gt; NAME</code>. It applies without a redeploy.</li></ol><p>Finally, <a href="./../deployment.html">verify a hosted turn</a>.</p>`,26)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
